window.__HOT_STORIES__ = {"schemaVersion":1,"updatedAt":"2026-11-23T13:07:36.059Z","stories":{"c5ab5cf5-6316-4ad6-9d74-f0b378a2b064":{"publicId":"c5ab5cf5-6316-4ad6-9d74-f0b378a2b064","title":"OpenAI 提议以困惑度设共同安全上限，微软公布可比数据","status":"active","sourceCount":11,"reportCount":15,"firstReportAt":"2026-11-22T00:00:00.000Z","latestAt":"2026-11-23T01:00:23.127Z","latest":"微软 AI 负责人苏莱曼支持 OpenAI 透明度倡议，公布 MAI-2 Base 评测结果","digest":"OpenAI 首席科学家 Jakub Pachocki 发表《Perplexity and Intelligence》，提议把困惑度（交叉熵损失）作为跨模型开发者的共享比较指标，并据此设立共同安全上限：超过门槛的进展须以人类理解 AI 行为的能力为前提。OpenAI 同时公开预训练 log-perplexity 走势图，覆盖 GPT-3.5 到 GPT-6.2 Astra 的 base model，并标注一个 internal model 点位。\n\nCEO Sam Altman 表态支持，称 OpenAI 正在大幅公开预训练进展，希望各方就共同限制达成一致；他还提议前沿模型开发者共同建立评估模型、红线测试安全案例的行业规范，包括共享透明度标准，并以困惑度等测量设定开发者承诺不逾越的共同上限，直到理解与监控 AI 行为的能力达到具体里程碑（如 CoT 监控器的后继技术）。首席研究官 Mark Chen 呼吁前沿实验室披露追踪进展的关键指标，并提出困惑度作为候选标准。\n\n微软 AI CEO Mustafa Suleyman 表示完全支持该倡议，并公布 MAI-2 Base 在 OpenAI 评测集上的 log-perplexity 为 0.819，与 GPT-5.6 Sol base 相当；他称两者使用同一 tokenizer 因而可直接比较，且微软能访问 OpenAI 评测集属于特殊情况。Dan Hendrycks 引用该文及公开曲线估算，自 GPT-4 以来预训练计算效率平均每年提升约 3–5 倍，大部分增益来自最近一年。上述内容目前仍是 OpenAI 方面的提议，尚未成为行业或公司的既定规则。","digestUpdatedAt":"2026-11-23T01:19:27.294Z","reports":[{"id":"ahiv28657urifplozo1csu3lg","title":"微软 AI 负责人苏莱曼支持 OpenAI 透明度倡议，公布 MAI-2 Base 评测结果","summary":"微软 AI 负责人穆斯塔法·苏莱曼在 X 平台表示完全支持 OpenAI 提高透明度的倡议，认为这是 AI 安全协调方面朝正确方向迈出的一步。微软承诺在双方共同保留的评测集上分享预训练进展，经 OpenAI 许可公布的 MAI-2 Base 对数困惑度为 0.819，与 GPT-5.6 Sol 基础模型处于相近水平，且因使用与 OpenAI 相同的分词器，数字可直接比较。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-23T01:00:23.127Z","url":"https://www.ithome.com/1/030/745.htm"},{"id":"l2sbkxmzbg1zq5xe2cazob89m","title":"Mustafa Suleyman 支持 OpenAI 透明度倡议，公布 MAI-2 Base 困惑度数据","summary":"Microsoft AI CEO Mustafa Suleyman 表示完全支持 OpenAI 的预训练透明度倡议，并公布 MAI-2 Base 在 OpenAI 评测集上的 log-perplexity 为 0.819，与 GPT-5.6 Sol base 相当，两者使用同一 tokenizer 因而可直接比较。","sourceName":"X：Mustafa Suleyman（Microsoft AI CEO） (@mustafasuleyman)","firstParty":false,"publishedAt":"2026-11-23T00:37:29.000Z","url":"https://x.com/mustafasuleyman/status/2124663594449318173"},{"id":"vfd82yb3feq7ixwb9uw6infzx","title":"OpenAI 首席科学家 Jakub 发文倡议用对数困惑度衡量底层智能进展","summary":"indigo 解读 OpenAI 首席科学家 Jakub 的倡议文「Perplexity and Intelligence」，主张行业用对数困惑度反映预训练阶段涌现的底层智能，以免 RL 阶段失控。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-23T00:26:48.000Z","url":"https://x.com/indigox/status/2124660902092042722"},{"id":"lev71ucng72fc2757tvu5e001","title":"OpenAI 首席科学家 Jakub Pachocki 提议为先进 AI 设共同开发门槛，警告 2027 年或现能力加速","summary":"OpenAI 首席科学家 Jakub Pachocki 发文提议 AI 企业建立行业统一标准，在安全监控能力可靠之前不突破约定的发展门槛，CEO 奥尔特曼公开支持。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-22T22:50:46.817Z","url":"https://www.ithome.com/1/030/720.htm"},{"id":"w6aesnkh72hkkxhr4ptrhddd9","title":"OpenAI 首席科学家 Jakub Pachocki 提议以 perplexity 作为限制 AI 发展速度的度量","summary":"OpenAI 首席科学家 Jakub Pachocki 发文提议以 perplexity 作为衡量 AI 进展的共同基准，用于在企业间建立发展速度的共同限制。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-22T21:14:07.000Z","url":"https://techcrunch.com/2026/11/22/openais-chief-scientist-has-thoughts-on-how-to-limit-ai-development/"},{"id":"w710a5d202zi2gg348cz01fob","title":"OpenAI 首席研究官 Mark Chen 呼吁前沿实验室共享关键指标并公开自家困惑度数据","summary":"OpenAI 首席研究官 Mark Chen 表示各实验室自写安全案例、自设护栏导致 AI 竞赛动态难以摆脱，呼吁前沿实验室披露追踪进展的关键指标，并提出困惑度作为候选标准。","sourceName":"X：Mark Chen（OpenAI 首席研究官，@markchen90）","firstParty":false,"publishedAt":"2026-11-22T19:55:58.000Z","url":"https://x.com/markchen90/status/2124592748099665943"},{"id":"uyaqmati59kykshezwugs41bh","title":"Greg Brockman 解读 OpenAI 基于困惑度的预训练共同安全上限提议","summary":"Greg Brockman 介绍 OpenAI《Perplexity and Intelligence》一文，主张基于困惑度等指标设立开发者承诺不逾越的共同安全上限，并配以明确的退出标准（如 CoT monitors 的后继工具问世）。他认为对齐与监控进展可能不够快，无法支撑预训练的充分加速，目标是形成逐级设限、控制发展节奏的共同框架。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-22T19:15:59.000Z","url":"https://x.com/gdb/status/2124582684840399311"},{"id":"ugbmwlfgci2rzkqvdevqn8a2b","title":"Suleyman 称赞 OpenAI 预训练透明度倡议","summary":"这非常重要。非常感谢 @merettm 和 OAI 为此发声倡导。","sourceName":"X：Mustafa Suleyman（Microsoft AI CEO） (@mustafasuleyman)","firstParty":false,"publishedAt":"2026-11-22T18:43:17.000Z","url":"https://x.com/mustafasuleyman/status/2124574455972364689"},{"id":"dks2nr0fsbmlkolagvqk6w4g7","title":"Dan Hendrycks 估算 GPT-4 以来预训练计算效率每年提升约 3–5 倍","summary":"Dan Hendrycks 引用 OpenAI 发布的《Perplexity and Intelligence》一文及其公开的基座模型困惑度曲线，估算自 GPT-4 以来预训练计算效率平均每年提升约 3–5 倍，即达到相同 loss 所需算力每年缩减至三分之一到五分之一。他指出大部分增益来自最近一年，这可能意味着今年的提升达到约 100 倍以上。","sourceName":"X：Dan Hendrycks (@hendrycks)","firstParty":false,"publishedAt":"2026-11-22T18:31:04.000Z","url":"https://x.com/hendrycks/status/2124571381295984764"},{"id":"u09xn1k898u9moe4eh0mrsq3b","title":"OpenAI 谈困惑度与AI安全标准","summary":"各实验室在白宫协议下同意建立标准和最佳实践，以提升其系统的安全性，我相信围绕困惑度使用的讨论可以进一步推进这些目标。","sourceName":"X：Sam Altman (@sama)","firstParty":false,"publishedAt":"2026-11-22T17:40:44.000Z","url":"https://x.com/sama/status/2124558713646428663"},{"id":"nrzd48iqj8z40nyvlmqhtlp80","title":"OpenAI 发布 Perplexity and Intelligence，公开预训练困惑度进展数据","summary":"OpenAI 发布文章 Perplexity and Intelligence，主张基于困惑度等测量设立共同安全门槛，超过门槛的进展应以对 AI 行为的理解能力为前提，并首次公开预训练进展数据。文中图表展示从 GPT-3.5 到 GPT-6.2 Astra 的 base model log-perplexity 走势，并标注了一个 internal model 点位。Noam Brown 转发称 AI 将影响所有人，包括内部模型在内，所有人都有权知道进展轨迹。","sourceName":"X：Noam Brown (@polynoamial)","firstParty":false,"publishedAt":"2026-11-22T17:26:43.000Z","url":"https://x.com/polynoamial/status/2124555186043818245"},{"id":"kxc2p9z20b5dlbk419t6hbp3d","title":"Sam Altman 提议前沿模型开发者共同建立评估与安全红线测试的行业规范","summary":"Sam Altman 提议各前沿模型开发者共同建立评估模型和红线测试安全案例的行业共同规范，包括共享透明度标准。他还建议基于困惑度等测量设定开发者承诺不逾越的共同上限，直到理解与监控 AI 行为的能力达到具体里程碑（例如 CoT 监控器的后继技术），形成规定开发首道上限及突破前所需条件的行业标准。","sourceName":"X：Sam Altman (@sama)","firstParty":false,"publishedAt":"2026-11-22T17:13:35.000Z","url":"https://x.com/sama/status/2124551883130114403"},{"id":"kbsk3p0n2qaxicnh39x32fvlh","title":"OpenAI 公开预训练进展呼吁共同安全限制","summary":"这是 OpenAI 一段时间以来发布的最重要的内容。\n\n我们正在对预训练进展提供大量透明度，希望我们能作为朋友就共同限制达成一致。我认为这将非常明智，有助于确保安全与可控。","sourceName":"X：Sam Altman (@sama)","firstParty":false,"publishedAt":"2026-11-22T17:12:27.000Z","url":"https://x.com/sama/status/2124551594691932405"},{"id":"lwm6f6xtf8667axqr5snwas7u","title":"OpenAI 首席科学家 Jakub Pachocki 发文主张以 perplexity 设共同安全门槛并公开预训练进展","summary":"OpenAI 首席科学家 Jakub Pachocki 宣布为推动共同安全标准，提高 OpenAI 预训练进展的透明度，并发布文章《Perplexity and Intelligence》。他在文中主张基于 perplexity 等度量设立共同上限，超越门槛的进展应以理解 AI 行为的能力为前提，并附模型 log-perplexity 随时间下降的图表。","sourceName":"X：Jakub Pachocki（OpenAI 首席科学家，@merettm）","firstParty":false,"publishedAt":"2026-11-22T17:03:00.000Z","url":"https://x.com/merettm/status/2124549218995949967"},{"id":"r7kb35fpdwc1m2iqsmd310tdj","title":"OpenAI 提议以困惑度作为行业共享指标并公开内部预训练测量数据","summary":"OpenAI 撰文提议将 perplexity（交叉熵损失）确立为跨模型开发者比较和安全标准的共享指标，并公开其内部预训练测量数据。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-22T00:00:00.000Z","url":"https://openai.com/index/perplexity-and-intelligence"}]},"647b0945-9244-4f55-b509-0f3fa0f6fe51":{"publicId":"647b0945-9244-4f55-b509-0f3fa0f6fe51","title":"Lean 社区确认阿尔波格黎曼猜想证明正确","status":"active","sourceCount":13,"reportCount":19,"firstReportAt":"2026-11-20T15:37:46.650Z","latestAt":"2026-11-22T18:37:02.000Z","latest":"Gary Marcus 评 Levent Alpöge 借助 Claude 证明黎曼猜想：不是 AI 独立完成，也难以泛化","digest":"Anthropic 数学家莱文特·阿尔波格于 2026 年 11 月 20 日宣称，他与 AI 模型 Claude 合作证明了黎曼猜想，并称该方法可推广至广义黎曼猜想。他没有发表论文，只放出约 1700 万行 Lean 代码。Lean 与 Mathlib 社区随后发表声明，确认该证明正确：数十人独立运行得到相同结果，验证程序被设计为不会接受有缺陷的证明。\n\n此前 The Verge 报道称该证明尚未经独立验证，Anthropic 也未就阿尔波格的宣布置评。菲尔兹奖得主詹姆斯·梅纳德表示相信证明正确，依据是它已通过 Lean 形式化验证并经独立核实；但他同时称，证明需被理解才可能获得认可。\n\n关于功劳归属仍有分歧：阿尔波格称 Claude 在最后阶段远超自己并提出关键步骤，Gary Marcus 则强调这不是 AI 独立完成，而是数学家数月深度协作的成果。陶哲轩此前曾表示现有 AI 无法攻克该问题。","digestUpdatedAt":"2026-11-23T00:03:55.201Z","reports":[{"id":"se6kyzulklfw7rruyo86r3c46","title":"Gary Marcus 评 Levent Alpöge 借助 Claude 证明黎曼猜想：不是 AI 独立完成，也难以泛化","summary":"Gary Marcus 分析 Levent Alpöge 在 Claude 协助下疑似证明黎曼猜想一事，指出并非 AI 独立完成，而是这位数学家数月深度协作的成果。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-22T18:37:02.000Z","url":"https://garymarcus.substack.com/p/levent-alpoge-has-solved-the-riemann"},{"id":"ikpixx0j7414se1f6lww2csek","title":"Lean 与 Mathlib 社区确认 Levent Alpöge 黎曼猜想证明正确","summary":"Lean 与 Mathlib 社区发表声明，确认斯坦福数学家 Levent Alpöge 的黎曼猜想证明正确。Alpöge 于 2026 年 11 月 20 日以 1700 万行 Lean 代码发布该证明，数十人独立运行得到相同结果，且验证程序被设计为可证明不会接受有缺陷的证明。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-22T11:08:31.000Z","url":"https://the-decoder.com/lean-and-mathlib-community-officially-confirms-levent-alpoges-proof-of-the-riemann-hypothesis-is-correct/"},{"id":"p9h5xzsooms0foxeakoivy7qt","title":"菲尔兹奖得主梅纳德谈 Claude 合作证明黎曼猜想：相信证明正确，但需被理解才可能获认可","summary":"2022 年菲尔兹奖得主、牛津大学数学教授詹姆斯·梅纳德（James Maynard）在采访中表示，他认为 Anthropic 数学家莱文特·阿尔珀格（Levent Alpöge）与 Claude 合作完成的黎曼猜想证明是正确的，依据是该证明已通过 Lean 库形式化验证并经独立核实，且阿尔珀格过往有可靠记录。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-22T09:35:58.183Z","url":"https://www.ithome.com/1/030/677.htm"},{"id":"sur1rc2t4erze02ozroefugff","title":"Anthropic 数学家称与 Claude 可能证明黎曼猜想，同日人类数学家也给出证明","summary":"Anthropic 数学家 Levent Alpöge 称他与 Claude 可能证明了黎曼猜想，其证明长达 1740 万行 Lean。同日斯坦福数学家 Ravi Vakil 也发布了 Alessandro Masullo 对该猜想的证明，强调\"全由人类完成、无 AI 参与\"。Alpöge 的证明尚未被阅读核验，Masullo 的证明正由第三方检查并翻译为 Lean。","sourceName":"Azeem Azhar：Exponential View（RSS）","firstParty":false,"publishedAt":"2026-11-22T04:59:51.000Z","url":"https://www.exponentialview.co/p/ev-611"},{"id":"dkuj083l2zugx0h11b2yx9nkm","title":"黎曼猜想证明该归功于谁","summary":"以后黎曼猜想的证明，大家谈论更多的会是 Levent Alpöge 还是 Claude？","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-11-22T00:51:47.000Z","url":"https://x.com/SaitoWu/status/2124304802477982189"},{"id":"h0ti6sx4gk0mij86ymdl4szv3","title":"Grok 谈黎曼猜想的证明意义","summary":"对黎曼证明（目前为止）有用性的简单解释是：它消除了其他依赖于此的数学定理的条件性。\n\n当然，这也是超级智能取得的又一件令人震撼的成就……\n\nhttps://x.com/i/grok/share/bGVnYWN5_2b134790-72b8-47d6-b182-afb9b775bd6a","sourceName":"X：Elon Musk (@elonmusk, xAI)","firstParty":false,"publishedAt":"2026-11-21T18:49:42.000Z","url":"https://x.com/elonmusk/status/2124213680422387741"},{"id":"tje8i8y21ttk7jjmqet5bpxuq","title":"Anthropic 数学家称与 Claude 完成黎曼猜想证明，斯坦福数小时后发布纯人类竞争草稿","summary":"Anthropic 数学家 Levent Alpöge 周五宣布与 Claude 合作得到黎曼猜想及广义黎曼猜想的证明，证明以 Lean 语言分 14 个数据包发布，打印将超 25 万页。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-21T11:19:49.000Z","url":"https://the-decoder.com/hours-after-anthropic-claims-a-claude-proof-of-the-riemann-hypothesis-stanford-releases-an-all-human-competing-draft/"},{"id":"gpib9pwvar2m6yp9lsd5111ri","title":"Grok 谈黎曼猜想即将被解决","summary":"即使黎曼猜想最终尚未被完全解决，也很快就会了\n https://x.com/i/grok/share/bGVnYWN5_883c4778-e70d-4d39-b95d-c807591b80b0","sourceName":"X：Elon Musk (@elonmusk, xAI)","firstParty":false,"publishedAt":"2026-11-21T07:46:48.000Z","url":"https://x.com/elonmusk/status/2124046857659650295"},{"id":"h9u457be00wxrafjnehfbd9xl","title":"Rohan Paul 对照陶哲轩上月言论转发 Anthropic 数学家声称与 Claude 证明黎曼猜想的消息","summary":"Rohan Paul 引用转发称，Anthropic 数学家 Alpöge 表示他与 Claude 合作证明了 167 年未解的黎曼猜想，用时约六周，并把整个论证形式化为可机器检验的代码。作者同时附上陶哲轩上月访谈视频，陶哲轩当时表示现有 AI 无法攻克该问题，可能要到 2050 年前后由人类与 AI 结合才能取得进一步进展。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-21T07:20:09.000Z","url":"https://x.com/rohanpaul_ai/status/2124040149830926708"},{"id":"m3euloe30yztem02vuvbps0hs","title":"Anthropic 数学家 Levent Alpöge 声称与 Claude 合作证明黎曼猜想，同日现独立人类证明","summary":"Latent Space 汇总报道，Anthropic 数学家 Levent Alpöge 声称在与 Claude 合作下证明黎曼猜想，方法还覆盖广义黎曼猜想（GRH），仅发布 Lean 代码，散文版约 250,000 页；Elliot Glazer 确认形式化陈述为 GRH，并将 Lean 出错概率估计远低于 1%。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-21T05:02:13.000Z","url":"https://latent.space/p/ainews-riemann-hypothesis-proved-twice-independently/"},{"id":"iwtvrbj2ir0p8tr7ioqedaxwo","title":"Rohan Paul 引述 Thiel 2024 年预言回应 Claude 协助证明黎曼假设的说法","summary":"作者引用 @rohanpaul_ai 转述的消息称，Anthropic 数学 Alpöge 与 Claude 经约六周工作并形式化为机器可检验代码，宣称证明了 167 年未解的黎曼假设；作者补充 Peter Thiel 2024 年的说法，即 3 到 5 年内 AI 将能解开全美数学奥赛题，对数学研究者冲击更大。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-21T00:18:26.000Z","url":"https://x.com/rohanpaul_ai/status/2123934024628596896"},{"id":"gt179blsp9ok1jlaq3dxf521f","title":"Anthropic 数学家 Alpöge 称与 Claude 合作证明黎曼假设","summary":"Anthropic 数学家 Alpöge 宣布他与 Claude 合作证明了黎曼假设，称 Claude 提出关键步骤令他惊叹，工作历时约六周，并将整个论证形式化为机器可检验的代码。作者引用 Brian Greene 的说法，该证明约 25 万页，目前没有人类能够完全理解。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-20T22:40:25.000Z","url":"https://x.com/rohanpaul_ai/status/2123909356483940512"},{"id":"hsbh8rxnbqfw9pzhqq5rw4ihe","title":"Anthropic 数学家 Levent Alpöge 公布黎曼猜想的 Lean 可编译证明，Stanford 博士后同期发布纯人工证明","summary":"Anthropic 数学家 Levent Alpöge 宣布找到黎曼猜想的 Lean 可编译证明，该猜想提出于 1859 年，是千禧年大奖难题之一。他在文章中描述了与 Claude 协作完成论证的经历，数学界正通过 Zulip 讨论审查这一形式化结果。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-20T19:32:08.000Z","url":"https://techcrunch.com/2026/11/20/ai-claimed-a-solution-to-the-167-year-old-riemann-hypothesis-and-a-human-did-too/"},{"id":"jfvlkn07rmizh1b1tc1li2gjx","title":"Anthropic 数学家 Alpöge 称与 Claude 合作证明了黎曼猜想","summary":"Rohan Paul 转述：Anthropic 数学家 Alpöge 自称与 Claude 合作证明了有 167 年历史的黎曼猜想，方法是把两个作用于简化“玩具”版本的想法引向真问题，由 Claude 接手他未掌握的高级领域并提出关键步骤，全程约六周，并把论证形式化为机器可检验的代码。Alpöge 称 Claude 的一个想法会让同行数学家“从椅子上摔下来”，并表示该方法还可推广到广义黎曼猜想。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-20T17:38:08.000Z","url":"https://x.com/rohanpaul_ai/status/2123833283863789602"},{"id":"vu6fw8wmrs3xcln4u9gwzf1f4","title":"Anthropic数学家Alpöge宣布与Claude共同证明黎曼猜想，放出1737万行Lean代码","summary":"Anthropic数学家Levent Alpöge在其个人网站宣布与Claude共同给出黎曼猜想证明，未发论文，只放出175187个Lean文件、共1737万行代码。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-11-20T16:54:55.000Z","url":"https://mp.weixin.qq.com/s/8Zi3nfwddzFy6cZsK2_KxA"},{"id":"zd0je1l7flwl146g4067qfk36","title":"Anthropic 数学家 Levent Alpöge 称借助 Claude 证明了黎曼假设","summary":"Anthropic 数学家 Levent Alpöge 在个人网站声称与 Claude 合作证明了黎曼假设，并表示方法可推广至广义黎曼假设，证明以 Lean 形式化。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-20T16:34:13.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1010051/anthropic-riemann-hypothesis-millennium-prize-problem"},{"id":"ho0o6xob2p10mu52ghd7vyl81","title":"数学家 Levent Alpöge 自称与 Claude 合作发现黎曼猜想证明","summary":"Simon Willison 转述数学家 Levent Alpöge 的自述：他称与 Claude 合作发现了黎曼猜想（Riemann Hypothesis）的证明，且方法可推广到广义与扩展黎曼猜想，并已无假设地形式化论证。他形容过程中 Claude 在最后阶段远超自己，并将这一经历视为科学领域更大变革的开端，原文链接 alpo.ge/remark.pdf。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-20T16:30:48.000Z","url":"https://simonwillison.net/2026/Nov/20/levent-alpoge/"},{"id":"dwqvqargdgum4wu55gtbk6hxx","title":"François Chollet 转发 Anthropic 数学家称用 AI 证明黎曼猜想的报道","summary":"François Chollet 转发 Scientific American 的报道并评论 What a time to be alive。报道称一位 Anthropic 数学家声称用该公司 AI 解决了黎曼猜想，这一数学界最著名的未解难题，并附上原文链接。","sourceName":"X：Francois Chollet (@fchollet)","firstParty":false,"publishedAt":"2026-11-20T15:42:30.000Z","url":"https://x.com/fchollet/status/2123804181941424178"},{"id":"px9zx0q62ir3bw68722mfdqui","title":"Anthropic 数学家阿尔波格宣称与 Claude 合作完成黎曼猜想证明","summary":"Anthropic 数学家莱文特·阿尔波格当地时间 20 日在个人网站宣称，与 AI 模型 Claude 合作找到黎曼猜想的证明，并编写为 Lean 代码以待逐步验证。他称证明还覆盖范围更广的广义黎曼猜想，若获确认，大量以此为前提的数学结论将随之得到证实，论文原文见 https://alpo.ge/remark.pdf。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-20T15:37:46.650Z","url":"https://www.ithome.com/1/030/278.htm"}]},"fc5a905b-54af-4de4-9c7c-a366a60a9f84":{"publicId":"fc5a905b-54af-4de4-9c7c-a366a60a9f84","title":"智谱发布GLM-5.4旗舰模型并上线Coding Plan","status":"active","sourceCount":3,"reportCount":3,"firstReportAt":"2026-11-23T04:49:30.313Z","latestAt":"2026-11-23T10:27:11.000Z","latest":"智谱发布 GLM-5.4 循环 Transformer","digest":"智谱发布旗舰模型 GLM-5.4，并已向 GLM Coding Plan 全量用户开放，同步上线 ZCode、Trae、WorkBuddy、Qoder 等编码平台；用户将模型名设置为 glm-5.4 即可使用。智谱称，这是其首个采用 Loop Transformer 架构的旗舰模型，在 GLM-5 基座模型上让 28 层共享权重循环执行两轮，在参数量不变的情况下获得更深推理，智能水平达到 2-3T 级模型效果。\n\n该模型新增视觉能力，模型列表标注“1M”和“视觉”。智谱称其能力从传统编程延伸至视频、游戏、3D 着色器与 CAD 建模。Coding Plan V2、V3 及团队版用户使用 GLM-5.4 的额度提升至 1.5 倍。\n\n智谱称，API 将在完成安全评估后开放，模型权重计划以负责任的方式开源。","digestUpdatedAt":"2026-11-23T10:37:50.775Z","reports":[{"id":"dzf8rz0gf3la7bs8kew4l0zlz","title":"智谱发布 GLM-5.4 循环 Transformer","summary":"推出 GLM-5.4：搭载我们首个循环 Transformer 的通用编程模型。\n\n- 在 GLM-5 基座模型上循环已有层，实现更深层推理\n- 突破传统编程，延伸至视频、游戏、3D 着色器与 CAD 建模\n- 新增视觉能力，强化视觉编程\n\nAPI 将在安全评估后开放。模型权重将负责任地发布。\n\n技术博客：http://z.ai/blog/glm-5.4","sourceName":"X：智谱 Z.ai (@Zai_org)","firstParty":false,"publishedAt":"2026-11-23T10:27:11.000Z","url":"https://x.com/Zai_org/status/2124811995912286352"},{"id":"d4hhqnlmrclsx7d6idtvq95wz","title":"智谱发布GLM-5.4：首个Loop Transformer架构旗舰模型开启泛Coding","summary":"智谱发布旗舰模型GLM-5.4，为第一代采用Loop Transformer架构的模型，让28层共享权重循环执行两轮，在参数量不变下获得更深推理，智能水平达到2-3T级模型效果，并开启泛Coding能力。","sourceName":"公众号：智谱（GLM）","firstParty":false,"publishedAt":"2026-11-23T09:42:11.000Z","url":"https://mp.weixin.qq.com/s/D-IZr-QaT1or_chminK8IQ"},{"id":"dusrrvphsk2lm8qswivm4s0vs","title":"智谱 GLM-5.4 上线 Coding Plan，新增视觉能力","summary":"智谱官方运营人员宣布 GLM-5.4 模型已上线 Coding Plan，用户将模型名设置为 glm-5.4 即可使用。该模型新增视觉能力与更强的泛 Coding 能力，模型列表显示“1M”和“视觉”字样。V2、V3 及团队版用户的 GLM-5.4 使用额度提升至 1.5 倍，模型具体介绍信息暂未公布。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-23T04:49:30.313Z","url":"https://www.ithome.com/1/030/809.htm"}]},"0cf0f02a-0464-43db-b253-ed1878937b74":{"publicId":"0cf0f02a-0464-43db-b253-ed1878937b74","title":"Thinking Machines 开源循环模型 Inkling 2 Mini","status":"active","sourceCount":15,"reportCount":23,"firstReportAt":"2026-11-19T16:00:00.000Z","latestAt":"2026-11-23T06:55:25.030Z","latest":"Thinking Machines Lab 发布循环 Transformer 模型 Inkling 2 Mini","digest":"Thinking Machines Lab 发布开源权重模型 Inkling 2 Mini，采用循环 Transformer 架构：24 层中中间 12 层对每个 token 循环运行三次，首尾各六层只运行一次。模型总参数 26.4B，以 Apache 2.0 许可在 Hugging Face 发布完整权重及可变循环研究版本，并上线 Tinker 供推理和微调。\n\n官方称其可在 32GB 以上内存的 Mac 本地运行，也可在 NVIDIA DGX Spark 上运行；vLLM 提供 Day-0 支持，Ollama 预发布版可一条命令运行，Unsloth 称 1-bit 量化仅需 9GB 内存。评测方面，Artificial Analysis 智能指数得 20 分，ARC Prize 公布 ARC-AGI-2 得分 49.3%、每任务 $0.14，ARC-AGI-1 得分 84.5%、每任务 $0.06。\n\n循环架构引发可监控性担忧，Thinking Machines 称研究发现多次循环下 no-CoT 能力上升、思维链变短但仍可读，可监测性没有明显下降，并同步开源可变循环研究模型供外部实验；NDIF 已托管该模型及变体，提供白盒访问。各来源对激活参数表述不一，有 3B、3.4B、5.4B 三种说法。","digestUpdatedAt":"2026-11-23T07:16:41.320Z","reports":[{"id":"edmf4gjl80s2neuc4w0vjgsbp","title":"Thinking Machines Lab 发布循环 Transformer 模型 Inkling 2 Mini","summary":"Thinking Machines Lab（TML）于当地时间本月 20 日发布循环 Transformer 架构模型 Inkling 2 Mini。模型共 24 层，分四个 6 层模块，中间两个模块运行 3 次，并对专家节点从 384 个剪枝至 128 个；整体为 26.4B-A3.4B，考虑循环后每个词元激活权重 5.4B。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-23T06:55:25.030Z","url":"https://www.ithome.com/1/030/907.htm"},{"id":"kjnjqumqxr3miozl533n0arvh","title":"Thinky Machines 的 Inkling 2 Mini 登顶 HF 趋势榜","summary":"来自 @thinkymachines 的 Inkling 2 Mini 在 HF 上排名趋势第一（而来自 @UnslothAI 的 gguf 排名第二）。冲！","sourceName":"X：Clément Delangue（Hugging Face CEO） (@ClementDelangue)","firstParty":false,"publishedAt":"2026-11-21T18:31:39.000Z","url":"https://x.com/ClementDelangue/status/2124209139337331158"},{"id":"lgvi0yp86fz5e1bcj6trfdmn2","title":"Thinking Machines 发布开源权重模型 Inkling 2 Mini：26.4B 循环 MoE 可在 32GB Mac 上运行","summary":"Thinking Machines 发布开源权重循环 Transformer 模型 Inkling 2 Mini，总参数 26.4B、每 token 激活 3.4B，以 Apache 2.0 协议上架 Hugging Face。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-21T12:13:50.000Z","url":"https://www.marktechpost.com/2026/11/21/thinking-machines-inkling-2-mini-looped-transformer/"},{"id":"zixjeyn76xptget44y2x0v6jo","title":"Thinking Machines 发布开源循环 Transformer 模型 Inkling 2 Mini","summary":"Thinking Machines 发布开源模型 Inkling 2 Mini，一种循环 Transformer：24 层中的 12 层对每个 token 连跑三次，可在不生成更多文本的情况下延长内部推理，用更少 token 找到答案。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-21T10:33:02.000Z","url":"https://the-decoder.com/new-open-model-inkling-2-mini-thinks-in-loops-to-solve-problems-with-fewer-words-and-still-runs-on-a-laptop/"},{"id":"g6zp7jjfe2qwlvxvy6kqeobbm","title":"Inkling 2 Mini 机上离线造飞行模拟器","summary":"昨天团队申请批准“飞去任何地方”，为 Inkling 2 Mini 做飞机 bench：","sourceName":"X：Mira Murati（@miramurati）","firstParty":false,"publishedAt":"2026-11-21T00:47:56.000Z","url":"https://x.com/miramurati/status/2123941448479559687"},{"id":"msggmz9hhf3y7axytsidyx2nn","title":"Inkling 2 Mini 上架 Ollama，一条命令即可本地运行","summary":"Thinking Machines 转发 Ollama 的消息，Inkling 2 Mini 已随 Ollama 0.40.17 预发布版上架，用 ollama run inkling-2-mini 即可完全本地运行。该模型 5.4B 激活参数，token 会在中间层循环三次以加深推理，32GB 以上内存的 Mac 即可运行，面向编码、computer use、视觉推理和金融等智能体任务。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-21T00:14:07.000Z","url":"https://x.com/thinkymachines/status/2123932938492649575"},{"id":"f3e6qg9gdbj3ydgkpp6j2e7v6","title":"NDIF 上线 Thinking Machines 的 Inkling 2 Mini 白盒访问","summary":"Thinking Machines 宣布 NDIF 现已托管 Inkling 2 Mini 及其 variable-loop 变体，提供白盒访问，用户无需自有算力即可运行模型并干预其内部。NDIF 同时提供跨 loop 读取、patch 和引导模型激活的指南。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-21T00:08:41.000Z","url":"https://x.com/thinkymachines/status/2123931570436518245"},{"id":"rxpjyf0p90v7j0fkryq48oels","title":"Inkling 2 Mini 上架 Arena，可测试 26B 参数小模型","summary":"Arena 宣布 Thinking Machines 的 Inkling 2 Mini 上架 Agent Arena，这是一个 26B 参数的 looped transformer 小模型，官方分数即将公布。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-20T22:58:57.000Z","url":"https://x.com/arena/status/2123914021883756728"},{"id":"zvoeth3rwv2yj6b14ep4qfqf6","title":"Thinky Machines 登 ARC Prize 排行榜","summary":"@thinkymachines - 排行榜：https://arcprize.org/leaderboard\n- 复现公开结果：https://github.com/arcprize/arc-agi-benchmarking\n- 测试政策：https://arcprize.org/policy\n- 完整结果：https://arcprize.org/results/thinky-inkling-2-mini","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-20T21:04:37.000Z","url":"https://x.com/arcprize/status/2123885245426770229"},{"id":"rxj2v60ofmyzndb6xmv8fxsau","title":"ARC Prize 公布 Inkling 2 Mini 的 ARC-AGI (Verified) 成绩","summary":"ARC Prize 公布 thinkymachines 的 Inkling 2 Mini 在 ARC-AGI (Verified) 上的成绩：ARC-AGI-2 得分 49.3%、每任务 $0.14，ARC-AGI-1 得分 84.5%、每任务 $0.06。与 Inkling 2 Small 相比，在 ARC-AGI-2 上每任务成本低 47%，但得分低 32 个百分点。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-20T21:03:50.000Z","url":"https://x.com/arcprize/status/2123885049091440920"},{"id":"rwfbyx3cu15nqxzdbr5919hnt","title":"Thinking Machines 发布开源权重模型 Inkling 2 Mini，Artificial Analysis 智能指数得分 20","summary":"Thinking Machines 发布 Inkling 2 Mini，在 Artificial Analysis 智能指数得 20 分，处于智能与活跃参数的 Pareto 前沿。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-20T20:35:18.000Z","url":"https://x.com/ArtificialAnlys/status/2123877871316087012"},{"id":"h3c7hoefv74f6q02h3l5rfemm","title":"Unsloth 发布 Inkling 2 Mini 本地运行指南，26.4B MoE 模型可在 16GB 内存运行","summary":"Unsloth 提供了 Thinking Machines 新发布的 Inkling 2 Mini 的本地运行支持，这是一款 Apache 2.0 的 26.4B（激活 5.4B）MoE 模型，采用 Looped Transformer 架构和 1M 上下文。该模型 DeepSWE v1.1 得分 48.2%、SWE-Bench Pro v2 (Hard) 得分 77.9%，为其尺寸中最高；GGUF 已上传至 Hugging Face，1-bit 量化仅需 9GB 内存，4-bit 需 17-18GB，可通过 Unsloth 和 llama.cpp 运行。","sourceName":"X：Unsloth (@UnslothAI)","firstParty":false,"publishedAt":"2026-11-20T20:18:33.000Z","url":"https://x.com/UnslothAI/status/2123873656069877899"},{"id":"gj2mmwqy7kojuxu6j3eyy1pbn","title":"Thinking Machines 开源 Inkling 2 Mini（Apache 2.0）","summary":"Thinking Machines 发布 Inkling 2 Mini，以 Apache 2.0 协议开源，模型已上架 Hugging Face。作者称其达到开源 Agent 模型的 Pareto 前沿；对比表显示该模型 5.4B/26.4B 激活/总参数，在 AA Index、Vals Index、FrontierCode、DeepSWE 等基准上领先 Gemma 4 31B、Muse Glimmer 等对比模型。","sourceName":"X：Clément Delangue（Hugging Face CEO） (@ClementDelangue)","firstParty":false,"publishedAt":"2026-11-20T20:17:20.000Z","url":"https://x.com/ClementDelangue/status/2123873347393970488"},{"id":"q6orirqf2j4ccyt2oq8356s8c","title":"Thinking Machines 发布 Inkling 2 Mini：26B 参数 looped transformer 可在笔记本运行","summary":"Mira Murati 发布 Inkling 2 Mini，一个仅 26B 参数的 looped transformer，小到可在笔记本上运行，在 AA Index 得分 20.1，此前 Inkling 2 Small 有 594B 参数被认为过大。她称循环机制让模型多思考少输出，该规模下思维过程仍可监控，团队还同步开源了一个 variable-loop 研究模型供进一步研究。","sourceName":"X：Mira Murati（@miramurati）","firstParty":false,"publishedAt":"2026-11-20T20:14:06.000Z","url":"https://x.com/miramurati/status/2123872534970208421"},{"id":"fbixrtyecgwczbxheseom58ik","title":"Inkling 2 Mini 登陆 Ollama 与 DGX Spark","summary":"Inkling 2 Mini 可通过 @ollama 在 32GB 内存的 Mac 上运行，也可在 NVIDIA 的 DGX Spark 上运行。它已上线 Tinker，用于推理和微调，并已入驻 Tinker Playground。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-20T20:10:35.000Z","url":"https://x.com/thinkymachines/status/2123871647371501591"},{"id":"gar8sck1ea3i6zjs6vp0lzgjh","title":"Thinking Machines 发布 26B 参数的 Inkling 2 Mini","summary":"Thinking Machines 回应部分用户认为 Inkling 2 Small 的 594B 参数过大的反馈，发布 looped transformer 架构的 Inkling 2 Mini，仅 26B 参数。模型小到可在笔记本上运行，AA Index 得分 20.1，面向智能体任务，详情见 thinkingmachines.ai/news/inkling-2-mini/。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-20T20:10:34.000Z","url":"https://x.com/thinkymachines/status/2123871643797995872"},{"id":"s5n9o0z0bdu4kn5ip2rtrt4lc","title":"Inkling 2 Mini 循环 Transformer 可监控性研究","summary":"Inkling 2 Mini 是一个 24 层的循环 Transformer。中间 12 层循环三次；首尾各六层只运行一次。\n\n循环让模型在少写的同时进行更多推理，这引发了对可监控性的担忧。我们在发布过程中对此进行了研究。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-20T20:10:34.000Z","url":"https://x.com/thinkymachines/status/2123871645039464643"},{"id":"yewn8su7mvqeun52a9yovp1g3","title":"Thinking Machines 发布可变循环研究模型，发现 no-CoT 能力随循环次数提升","summary":"Thinking Machines 发现多次循环下 no-CoT 能力随循环次数上升，链式思维变短但仍可读，可监测性没有明显下降。团队同时发布一个可变循环研究模型，供其他人运行自己的实验。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-20T20:10:34.000Z","url":"https://x.com/thinkymachines/status/2123871646176166358"},{"id":"y7nk77dxae51qwi826gpmvbho","title":"Thinking Machines Lab 发布可跑在笔记本上的开源权重模型 Inkling 2 Mini","summary":"Thinking Machines Lab 发布开源权重模型 Inkling 2 Mini，采用循环 Transformer 架构，将中间 12 层每 token 运行三次，总参数 26.4B、激活 3.4B，内存占用约 20GB，可在 32GB 内存以上的 Mac 本地运行。","sourceName":"Thinking Machines Lab：News（网页）","firstParty":true,"publishedAt":"2026-11-20T07:00:00.000Z","url":"https://thinkingmachines.ai/news/inkling-2-mini/"},{"id":"uy9a6qm6p671jbogn3c1r4b98","title":"Hugging Face 联合 Thinking Machines Lab 发布本地多模态模型 Inkling 2 Mini","summary":"Hugging Face 与 Thinking Machines Lab 合作发布面向本地部署的多模态 MoE 模型 Inkling 2 Mini，总参数约 26B、每 token 激活 3B。","sourceName":"Hugging Face 官方团队博客","firstParty":true,"publishedAt":"2026-11-20T00:00:00.775Z","url":"https://huggingface.co/blog/inkling2mini"},{"id":"ve55b8roz3vc4cq7t5ohtsixt","title":"vLLM Day-0 支持 Thinking Machines 循环模型 Inkling 2 Mini","summary":"Thinking Machines 发布 Inkling 2 Mini，vLLM 在 Blackwell、Hopper 和 DGX Spark 上提供 Day-0 支持。","sourceName":"vLLM 官方博客（RSS）","firstParty":true,"publishedAt":"2026-11-20T00:00:00.000Z","url":"https://vllm.ai/blog/2026-11-20-inkling2-mini"},{"id":"j84gvc6i39lzdh4f4t1p8w5ju","title":"Thinking Machines 发布开源权重循环架构模型 Inkling 2 Mini","summary":"Thinking Machines 发布开源权重循环 Transformer 模型 Inkling 2 Mini，Apache 2.0 许可，26B 总参数、5.4B 激活参数的 MoE 架构，支持文本和图像输入、1M token 上下文窗口，可在 MacBook 或 DGX Spark 上运行。","sourceName":"Artificial Analysis 完整文章（网页）","firstParty":true,"publishedAt":"2026-11-19T16:00:00.000Z","url":"https://artificialanalysis.ai/articles/inkling-2-mini"},{"id":"tfvuikboev6dm8u2rck1dx8fb","title":"Goodfire 解析 Thinking Machines 开源模型 Inkling 2 Mini 的内部机制","summary":"Goodfire Research 发布对 Thinking Machines 开源权重模型 Inkling 2 Mini 的可解释性研究，该模型有 24 层，采用 attention residuals 和中间块循环三次的架构。","sourceName":"Goodfire Research（网页）","firstParty":true,"publishedAt":"2026-11-19T16:00:00.000Z","url":"https://www.goodfire.com/research/interpreting-inkling-2-mini"}]},"fcbdc9a0-bdf5-473c-9f26-7a51a8deb2e3":{"publicId":"fcbdc9a0-bdf5-473c-9f26-7a51a8deb2e3","title":"特斯拉FSD v15下月推送，马斯克介绍天空箭头导航","status":"active","sourceCount":3,"reportCount":4,"firstReportAt":"2026-11-21T20:26:59.000Z","latestAt":"2026-11-22T23:40:36.000Z","latest":"特斯拉新 FSD 显示由车机端约 1B diffusion 模型实时生成","digest":"特斯拉 FSD v15 将于下个月开始推送。马斯克转发更新说明称，v15 升级了端到端驾驶网络的各部分，包括与 Robotaxi 和 Optimus 共享的视觉编码器，将关键干预率提升 25 倍；官方还称体验更丝滑，并支持实时街景渲染。这些安全与体验说法目前没有验证数据。\n\n马斯克介绍，v15 中特斯拉 AI 计算机会像电子游戏一样，用天空中的箭头重新渲染现实来指示转弯，用户可点击“现实重现器”上的任意一点让车辆驶向该处。更新说明还列出导航、泊车选择、驾驶员监测、障碍物检测、坑洼与积水规避及 Autoshift 换挡等改进。\n\n据作者 Dash 引用马斯克的解释，新版 FSD 显示画面由车机端约 1B 的条件 mean-flow diffusion 模型实时生成，而非传统 3D 渲染；该模型基于 Universal Vision Encoder 特征，每秒 18 帧时用半个 TRIP 引擎算力生成 8 帧 36fps 的视频块，当前延迟偏高，但已有可削减约 35% 延迟的方案。","digestUpdatedAt":"2026-11-22T23:53:14.525Z","reports":[{"id":"bv25ion2dcrlt1fqi7m7a014j","title":"特斯拉新 FSD 显示由车机端约 1B diffusion 模型实时生成","summary":"作者引用 Elon Musk 的解释：特斯拉新版 FSD 显示画面是 AI 视频实时生成的，不走传统 3D 渲染。车机端运行一个约 1B 的条件 mean-flow diffusion 模型，基于 Universal Vision Encoder 特征，每秒 18 帧时用半个 TRIP 引擎算力生成 8 帧 36fps 的视频块，当前延迟偏高但已有可削减约 35% 延迟的方案。","sourceName":"X：Dash (@dashhuang)","firstParty":false,"publishedAt":"2026-11-22T23:40:36.000Z","url":"https://x.com/DashHuang/status/2124649277951766806"},{"id":"szg9dx5ua3s1e0cklbgssy953","title":"Elon Musk 称赞 Tesla FSD V15 是全新架构的出色版本","summary":"Elon Musk 转发并称赞 Tesla FSD V15，称其采用全新架构，驾驶智能超越人类。引用的完整更新说明称 v15 升级了端到端驾驶网络的各部分，包括与 Robotaxi 和 Optimus 共享的视觉编码器，将关键干预率提升 25 倍；新增 Tesla Reality View 端到端可视化，并改进导航、泊车选择、驾驶员监测、标志和小动物等障碍物检测、坑洼与积水规避以及 Autoshift 换挡。","sourceName":"X：Elon Musk (@elonmusk, xAI)","firstParty":false,"publishedAt":"2026-11-22T00:11:51.000Z","url":"https://x.com/elonmusk/status/2124294755316310346"},{"id":"xriwds9rtl5niekinxe2uwxsu","title":"FSD v15 下月推送：25x 安全与实时街景渲染","summary":"FSD v15 将于下个月开始推送，官方称安全性提升 25x、体验更丝滑，并支持实时街景渲染。推文认为本地算力富足到可做高质量渲染，效果堪比 GTA 6，并猜测部分地区的 FSD 或已可无监督运行。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-21T22:10:40.000Z","url":"https://x.com/indigox/status/2124264257273643371"},{"id":"mbi7z2u3erlzmlonr9dmanwh5","title":"特斯拉FSD V15天空箭头导航","summary":"在FSD V15中，特斯拉AI计算机像电子游戏一样，用天空中的箭头重新渲染现实来指示转弯。\n\n你可以点击现实重现器上的任意一点，让车辆驶向该处。","sourceName":"X：Elon Musk (@elonmusk, xAI)","firstParty":false,"publishedAt":"2026-11-21T20:26:59.000Z","url":"https://x.com/elonmusk/status/2124238164512714925"}]},"7a64c34c-2019-47e0-9ceb-2faff7425307":{"publicId":"7a64c34c-2019-47e0-9ceb-2faff7425307","title":"蚂蚁开源首个多模态医疗大模型 LingSante-3.1-air-VL","status":"active","sourceCount":5,"reportCount":5,"firstReportAt":"2026-11-21T16:00:00.000Z","latestAt":"2026-11-23T03:00:00.000Z","latest":"蚂蚁开源医疗多模态模型 LingSante-3.1-air-VL，总参数 124B、激活 5.5B","digest":"蚂蚁集团发布并开源了多模态医疗大模型 LingSante-3.1-air-VL，称这是其首个开源的多模态医疗大模型。模型基于 Ling-3.0-flash-VL 构建，总参数 124B、激活参数 5.5B，上下文窗口最高 256K token，权重已在 Hugging Face 和 ModelScope 开放，同时开放 API 接入。\n\n据蚂蚁百灵介绍，该模型能力覆盖医学影像理解、报告生成、医疗推理，以及多模态搜索和工具调用；Rohan Paul 的报道称其可生成胸片报告。蚂蚁百灵邀请用户用真实医疗图片、报告与业务场景测试其实际表现，但未公布测试结果。\n\n在阿福医疗健康生态大会上，蚂蚁进一步宣布蚂蚁百灵医疗健康大模型家族全面开源，家族含大语言模型、实时音视频模型、预测模型和安全防护模型，其中医生专业个人版多模态模型为 124B、医疗机构版医疗智能体大模型为 562B；官方称最轻量版一台笔记本即可部署，并称疾病种类、准确率超越全球多个专用模型。上述性能说法来自蚂蚁方面，尚未见独立验证。","digestUpdatedAt":"2026-11-23T08:02:49.470Z","reports":[{"id":"bx13wv0ouln40ga2uk857j65c","title":"蚂蚁开源医疗多模态模型 LingSante-3.1-air-VL，总参数 124B、激活 5.5B","summary":"蚂蚁集团发布并开源首个多模态医疗大模型 LingSante-3.1-air-VL，基于 Ling-3.0-flash-VL 构建，总参数 124B、激活 5.5B，上下文窗口最高 256K token，权重已在 Hugging Face 和 ModelScope 开放。","sourceName":"公众号：蚂蚁百灵（Ling）","firstParty":false,"publishedAt":"2026-11-23T03:00:00.000Z","url":"https://mp.weixin.qq.com/s/c1qVtC3rXNK1Wqd59NxSAQ"},{"id":"b6fbn7er8crslhg72fh3hkl8y","title":"蚂蚁百灵医疗健康大模型宣布全面开源，最轻量版一台笔记本即可部署","summary":"蚂蚁在阿福医疗健康生态大会上宣布蚂蚁百灵医疗健康大模型全面开源，家族包含大语言模型、实时音视频模型、预测模型和安全防护模型，支持疾病未来六年的发病风险预测。据现场信息，模型含医生专业个人版多模态模型（124B）和医疗机构版医疗智能体大模型（562B），最轻量版一台笔记本即可部署，官方称疾病种类、准确率超越全球多个专用模型。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-23T02:56:54.250Z","url":"https://www.ithome.com/1/030/784.htm"},{"id":"lrq0kpclh1u861beihn823d26","title":"蚂蚁集团开源医疗多模态模型 LingSante-3.1-air-VL，可生成胸片报告","summary":"蚂蚁集团开源多模态医疗模型 LingSante-3.1-air-VL，总参数 124B、每 token 激活 5.5B 的 MoE 架构，结合医学影像理解、报告生成、医学推理与多模态搜索和工具使用。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-22T21:25:30.000Z","url":"https://x.com/rohanpaul_ai/status/2124615279108137021"},{"id":"qyoj0zhunq0n1xmzm53yns55x","title":"蚂蚁百灵开源医疗多模态模型 LingSante-3.1-air-VL，总参数 124B、激活 5.5B","summary":"蚂蚁百灵发布开源多模态医疗模型 LingSante-3.1-air-VL，总参数 124B、激活参数 5.5B，结合医学影像理解、报告生成、医疗推理与多模态搜索和工具调用。","sourceName":"X：蚂蚁百灵 (@AntLingAGI)","firstParty":false,"publishedAt":"2026-11-22T17:26:19.000Z","url":"https://x.com/AntLingAGI/status/2124555085640610194"},{"id":"q0jpjfgyy1mkaupvp0j18y127","title":"蚂蚁开源 LingSante-3.1-air-VL 医疗多模态模型","summary":"蚂蚁集团发布并开源 LingSante-3.1-air-VL，是其首个开源多模态医疗大模型，基于 Ling-3.0-flash-VL 构建，总参数量 124B、激活参数 5.5B，支持文本与图像输入和最高 256K token 上下文窗口。","sourceName":"蚂蚁百灵：Developer Blog（网页）","firstParty":true,"publishedAt":"2026-11-21T16:00:00.000Z","url":"https://developer.ant-ling.com/zh-CN/blogs/lingsante-3.1-air-vl"}]},"5e931c88-3e7c-4f18-be7f-6c6902aa59b2":{"publicId":"5e931c88-3e7c-4f18-be7f-6c6902aa59b2","title":"蚂蚁开源560B医疗MoE模型LingSante-3.1-flash","status":"active","sourceCount":5,"reportCount":5,"firstReportAt":"2026-11-21T16:00:00.000Z","latestAt":"2026-11-23T03:00:00.000Z","latest":"蚂蚁百灵发布开源医疗模型 LingSante-3.1-flash，融合医学推理与工作流执行","digest":"蚂蚁百灵发布开源权重医疗混合专家模型 LingSante-3.1-flash，总参数 560B、每 token 激活约 25B，权重以 MIT 许可在 Hugging Face 开放。蚂蚁百灵称，该模型以 Ling-3.1-flash 为通用底座，统一多项医疗能力并保留通用能力，覆盖复杂医疗推理、长程工作流执行和专业行为对齐；采用 Hybrid-linear MoE 架构（63 层 KDA 与 9 层 Gated MLA，512 个路由专家加 1 个共享专家），支持最长 1M 上下文。\n\n随后 inclusionAI 发布基于该模型的混合 MXFP4 量化版本 LingSante-3.1-flash-MXFP4，上下文窗口为 262,144 token，同样采用 MIT 许可。蚂蚁百灵称，开发者可通过官方入口下载 FP8 及 MXFP4 版本，或经蚂蚁集团数字科技大模型服务平台在线试用、API 接入。inclusionAI 声明该模型不是医疗器械，不得作为诊断、处方或治疗的独立依据。","digestUpdatedAt":"2026-11-23T08:02:34.849Z","reports":[{"id":"ltlj255icukkenix60rrt3jc1","title":"蚂蚁百灵发布开源医疗模型 LingSante-3.1-flash，融合医学推理与工作流执行","summary":"蚂蚁百灵发布开源医疗模型 LingSante-3.1-flash，基于 Ling-3.1-flash 通用底座，总参数量 560B、每 token 激活约 25B，支持最长 1M 上下文，采用 Hybrid-linear MoE 架构（63 层 KDA 与 9 层 Gated MLA，512 个路由专家加 1 个共享专家）。","sourceName":"公众号：蚂蚁百灵（Ling）","firstParty":false,"publishedAt":"2026-11-23T03:00:00.000Z","url":"https://mp.weixin.qq.com/s/UF7xL0pR842Jo-c7TZUWAw"},{"id":"mfek1ubzv47lhr539wpaoagfd","title":"蚂蚁集团发布医疗 MoE 模型 LingSante-3.1-flash，560B 参数权重以 MIT 许可开源","summary":"蚂蚁集团发布开源权重医疗 MoE 模型 LingSante-3.1-flash，总参数 560B、每 token 激活 25B，权重以 MIT 许可在 Hugging Face 开放。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-22T19:22:49.000Z","url":"https://x.com/rohanpaul_ai/status/2124584403695435777"},{"id":"xaoz6pmbhm1e0edczgo89w03l","title":"蚂蚁百灵发布开源权重医疗模型 LingSante-3.1-flash，560B 总参数 25B 激活","summary":"蚂蚁百灵发布开源权重 MoE 模型 LingSante-3.1-flash，总参数 560B、每 token 激活 25B，统一多项医疗能力并保留通用能力，覆盖复杂医疗推理、长程工作流执行和专业行为对齐。","sourceName":"X：蚂蚁百灵 (@AntLingAGI)","firstParty":false,"publishedAt":"2026-11-22T15:22:28.000Z","url":"https://x.com/AntLingAGI/status/2124523916819648945"},{"id":"kds8la9kifhqnc1v2ffgxr7i9","title":"蚂蚁 inclusionAI 开源 LingSante-3.1-flash-MXFP4 医疗 MoE 模型","summary":"蚂蚁 inclusionAI 在 HuggingFace 发布 LingSante-3.1-flash-MXFP4，这是基于 LingSante-3.1-flash 的混合 MXFP4 量化开源权重模型，主模型约 560B 参数、每 token 激活约 25B，配置 262,144 token 上下文窗口。","sourceName":"蚂蚁 inclusionAI：HuggingFace 新模型","firstParty":true,"publishedAt":"2026-11-22T03:19:38.000Z","url":"https://huggingface.co/inclusionAI/LingSante-3.1-flash-MXFP4"},{"id":"hzy9ajwl8139dnxk4sh56kjon","title":"蚂蚁百灵发布开源医疗模型 LingSante-3.1-flash","summary":"蚂蚁百灵推出 LingSante-3.1-flash，以 560B 总参数、每 token 激活约 25B 的 Hybrid-linear MoE 架构（最长 1M 上下文）原生融合医学推理与工作流执行能力。","sourceName":"蚂蚁百灵：Developer Blog（网页）","firstParty":true,"publishedAt":"2026-11-21T16:00:00.000Z","url":"https://developer.ant-ling.com/zh-CN/blogs/lingsante-3.1-flash"}]},"82c796c0-3bf1-4c3a-8368-56913b4bf85d":{"publicId":"82c796c0-3bf1-4c3a-8368-56913b4bf85d","title":"Anthropic 上市首日收涨 17%，次日回落","status":"active","sourceCount":25,"reportCount":121,"firstReportAt":"2026-10-25T16:00:00.000Z","latestAt":"2026-11-21T15:00:00.000Z","latest":"The Verge 播客：Anthropic IPO 后能否继续把安全放在第一位","digest":"Anthropic 于 11 月 19 日在纳斯达克上市，IPO 定价每股 83 美元，高于 70 至 78 美元的发行区间，发行 9.8 亿股 A 类普通股，公司募资约 813 亿美元；加上七家算力供应商按发行价合计认购 260 亿美元无投票权股份，总募资超过 940 亿美元。首日开盘 111.50 美元、盘中一度达 115.10 美元，市值一度超过 2 万亿美元，收盘回落至 97.17 美元，较发行价涨 17.07%；IT之家按此计算市值约 1.27 万亿美元，另有报道按完全稀释口径计算约 1.76 万亿美元。上市第二天股价跌逾 9% 至 88.17 美元，接近发行价，同期 AI 相关股票和全球主要股指下挫。\n\n治理上，七位联合创始人通过创始人控制的 LLC 持有超级投票权股份，在多数股东投票中保留 50.1% 控制权；Amazon 持股 14.7%、Google 持股 13.7%，均为无投票权股份。七位创始人各出售约 340 万股，按发行价每人套现约 2.8 亿美元，合计 19.5 亿美元，并承诺将个人持股的 80% 用于慈善，公司称该承诺可自愿撤回、不具法律约束力。多家银行以美国出口管制为由，拒绝或低配中国大陆和香港投资者的认购。","digestUpdatedAt":"2026-11-21T15:22:16.143Z","reports":[{"id":"m1mfbrq5o7kgdqcjxe6eoj8pk","title":"The Verge 播客：Anthropic IPO 后能否继续把安全放在第一位","summary":"The Verge 的 Nilay Patel 与资深 AI 记者 Hayden Field 对谈 Anthropic 在纳斯达克上市（发行价 $83，一度涨至 $111）后的前景，探讨其能否在公开市场压力下继续投入 AI 安全。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-21T15:00:00.000Z","url":"https://www.theverge.com/podcast/1038701/anthropic-ipo-ai-safety-openai-nvidia-structure"},{"id":"ufyn252g3i251j0mfwy8xth9r","title":"Anthropic 破纪录 IPO 未能止住 AI 抛售，全球股市下挫","summary":"Anthropic 上市第二天股价跌逾 9% 至 $88.17，接近 $83 发行价，其破纪录 IPO 未能止住 AI 相关公司抛售。周五 Nasdaq 跌 2%，SanDisk 跌 14%、Micron 跌 10%；亚洲股市创 2020 年以来最差一周，台湾加权指数跌 6.7%、日经跌 5%、Kospi 跌 5.5%，SoftBank 单日跌 14.5%。","sourceName":"Hacker News：AI 热帖","firstParty":false,"publishedAt":"2026-11-20T13:53:13.000Z","url":"https://www.theguardian.com/business/2026/nov/20/global-stock-markets-slump-anthropic-ipo-ai-sell-off"},{"id":"t3mx9fwmjqz97bj0zwxxtkkiq","title":"Anthropic 以 83 美元定价完成史上最大 IPO，上市首日估值近 2 万亿美元","summary":"Anthropic 以每股 83 美元在纳斯达克上市（代码 $ANT），融资 813 亿美元超过 SpaceX 成为史上最大 IPO，首日开盘价 111.50 美元、较发行价高 34.3%，完全稀释估值约 2 万亿美元。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-20T07:12:24.000Z","url":"https://latent.space/p/ainews-anthropic-successfully-completes-largest-ipo-in-history-valued-at-1-5t/"},{"id":"j96pobdmcb200kk2baf62615v","title":"Anthropic IPO 募资 813 亿美元创纪录，市值达 1.76 万亿美元引发安全争议","summary":"Anthropic 周四在纳斯达克上市，募资 813 亿美元，为史上最大 IPO，收盘市值 1.76 万亿美元，成为全球最大公共利益公司。CEO Dario Amodei 表示将按必要节奏推进 AI 训练与部署，不受商业或政治压力影响。","sourceName":"Platformer（热点 RSS）","firstParty":false,"publishedAt":"2026-11-20T01:37:44.000Z","url":"https://www.platformer.news/anthropic-goes-public/"},{"id":"hdvaqa4fp3ug2ozttf2n3tyuf","title":"Anthropic 七位创始人 IPO 套现近 20 亿美元，融资规模创纪录","summary":"Anthropic 上市融资 813 亿美元，其中七位创始人各出售约 340 万股，按 83 美元的发行价每人套现约 2.8 亿美元，合计 19.5 亿美元。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-20T00:43:50.000Z","url":"https://techcrunch.com/2026/11/19/anthropics-7-founders-cashed-out-nearly-2b-in-record-breaking-ipo/"},{"id":"k9l5dt0zbhvw3qiy58vzd95so","title":"Anthropic 纳斯达克上市首日收涨 17%，市值约 1.76 万亿美元","summary":"Anthropic 纳斯达克上市首日收于 97.17 美元、涨 17%，盘中一度较 83 美元发行价涨 38.7% 至 115.10 美元后回落。收盘完全稀释市值约 1.76 万亿美元，成为美国市值第 7 大公司；当日纳斯达克综合指数跌超 2%，部分散户卖出其他 AI 股套现认购新股。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-20T00:35:48.000Z","url":"https://x.com/rohanpaul_ai/status/2123576007282377061"},{"id":"e7xjysyuhq3nk3kvhci7lwx1c","title":"Anthropic 纳斯达克上市首日大涨 17%，市值达 1.27 万亿美元，IPO 募资 813 亿美元成史上最大","summary":"Anthropic 于 11 月 19 日在纳斯达克上市，首日收盘 97.17 美元，较 83 美元发行价上涨 17.07%，市值约 1.27 万亿美元。按 IPO 募资额计，本次募资 813 亿美元超过 SpaceX 6 月的 750 亿美元，为史上最大规模首次募股；公司每股收益为 -59.62 美元，尚未稳定盈利。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-19T22:41:40.427Z","url":"https://www.ithome.com/1/029/748.htm"},{"id":"dz0kkwkofq1dq1vzqqjgl0gyr","title":"Dario Amodei 谈丧父之痛与AI救人信念","summary":"Dario Amodei 分享说，他和妹妹、联合创始人 Daniela 的父亲因一种疾病去世，而那种病在他父亲去世仅几年后就变得可以治愈了。\n这份失去推动他投身生物学，也至今支撑着他的信念：AI 能让治愈更早到来。\n\n- Dario 是在当天纳斯达克开盘钟声前、于纳斯达克门前发表这番讲话的。\n\n----\n完整视频见“CNBC Television”YouTube 频道，（链接见评论）","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-19T21:15:23.000Z","url":"https://x.com/rohanpaul_ai/status/2123525569229078698"},{"id":"ps6iefgolixjza74xrxlf534q","title":"Anthropic IPO 开盘半小时下跌 13%，为 2008 年以来大型 IPO 最差开局","summary":"Gary Marcus 认为 Anthropic 的 IPO 看起来救不了低迷的科技行业。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-19T20:36:26.000Z","url":"https://garymarcus.substack.com/p/breaking-it-doesnt-look-anthropics"},{"id":"om8tbc6yznfxjsr25c29nb7mg","title":"WSJ：Anthropic IPO 定价 83 美元/股，或造约 600 名亿万美元级持股员工","summary":"WSJ 报道 Anthropic IPO 以每股 83 美元定价，估算约 600 名员工持股价值将超过 1 亿美元。该估算来自私募股权交易平台 Hill[.]com，其还预计约 2800 名员工持股超 1000 万美元，5000 多人的员工队伍中大多数人将超过 100 万美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-19T19:55:38.000Z","url":"https://x.com/rohanpaul_ai/status/2123505498419020007"},{"id":"b4uhmr8awqlofbouq18xga1qz","title":"Anthropic IPO 定价超出区间，开盘大涨 30%，市值一度达 2 万亿美元","summary":"Anthropic 完成 IPO，发行价超出区间且上调发行规模，开盘大涨 30%，市值一度达 2 万亿美元。文章称这是有史以来规模最大的 IPO（含私募配售），大幅超过 SpaceX，并指出此次上市还有多处罕见之处。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-11-19T19:36:02.000Z","url":"https://www.newcomer.co/p/anthropic-broke-all-the-startup-rules"},{"id":"he4xlj1y3ab1n3dfe8qvj3he9","title":"Anthropic IPO 慈善资金或达 1560 亿美元","summary":"TechCrunch 报道，Anthropic 上市后其公益基金 PBF 获配近 8.5 亿股（5%），按约 $95 股价约合 800 亿美元捐赠资金，估值较 $83 发行价每涨 50% 可再增持 2%。员工已认捐约 230 亿美元股票，公司按 3:1 或 1:1 配捐后总额约达 1560 亿美元，相当于 2025 年全美慈善捐款的四分之一，资金可能主要流向 AI 安全研究和 EA 相关慈善机构。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-19T19:10:45.000Z","url":"https://techcrunch.com/2026/11/19/anthropics-ipo-could-deliver-156-billion-to-charity/"},{"id":"gp3hccimt42ak2uh82nrpty65","title":"indigo 转发 Dario Amodei 为 Anthropic IPO 在 Nasdaq 敲钟","summary":"indigo 转发 @YahooFinance 的画面，Dario Amodei 在 Nasdaq 为 Anthropic IPO 敲响开市钟。作者恭喜这家最\"人类\"的科技公司上市，并调侃其敲钟鼓掌的样子怎么像是 AI 生成的。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-19T17:14:14.000Z","url":"https://x.com/indigox/status/2123464879961186584"},{"id":"bj8r4lnrbcoi5cl1asnyn6qt5","title":"Anthropic CEO Dario Amodei 就公司 IPO 发表声明","summary":"Anthropic CEO Dario Amodei 就公司 IPO 发表声明，称今天让公司财务地位更稳固，并强调不会向商业或政治压力低头，将放慢 AI 训练与部署节奏以确保安全和人类可控。声明以生物学背景和 Claude 在科研中的应用为例阐述使命，同时承认滥用、经济冲击和失控等风险，倡导行业「向顶部竞赛」。","sourceName":"X：Anthropic (@AnthropicAI)","firstParty":false,"publishedAt":"2026-11-19T17:01:26.000Z","url":"https://x.com/AnthropicAI/status/2123461658890686863"},{"id":"gklqioeodqeuqgz3lttg83ztv","title":"Anthropic 登陆纳斯达克，开盘价 111 美元较发行价高出 33%","summary":"Anthropic 在纳斯达克完成 IPO，开盘几分钟内股价达 111.50 美元，较 83 美元发行价高出 33%，发行价已超过公司此前 70 至 78 美元的预期区间。本次发行募资超过 810 亿美元，叠加同期私募融资后公司现金储备预计达 2200 亿美元；按开盘价计算市值超过 2 万亿美元，CEO Dario Amodei 在开盘致辞中强调公司对安全的承诺。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-19T16:59:23.000Z","url":"https://techcrunch.com/2026/11/19/anthropic-hits-nasdaq-exchanges-at-110-27-above-ipo-price/"},{"id":"rdgmufd2evohgemd2yh9qe2dy","title":"Anthropic 登陆纳斯达克，首日以 $111.50 开盘","summary":"Anthropic 正式在纳斯达克上市，代码 ANT，以 $111.50 开盘，高于 $83 的发行价，对应估值约 $1.5 万亿。其 S-1 文件披露上半年净亏损 $80.7 亿（主要来自不影响业务的会计费用）、营收 $16.3B，并保留创始人而非股东控制公司的治理结构；CEO Dario Amodei 表示将按需放缓 AI 训练与部署以确保安全，不屈服于商业或政治压力。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-19T16:52:01.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1035384/anthropic-ipo-trading-nasdaq"},{"id":"hzlbq0fxcls8sxek76qoq63v8","title":"Anthropic 股票上市首日开盘 111.50 美元，较 83 美元发行价涨约 34%","summary":"Anthropic 股票上市首日以每股 111.50 美元开盘，较每股 83 美元的 IPO 发行价上涨约 34%。","sourceName":"X：Kate Clark (@KateClarkTweets)","firstParty":false,"publishedAt":"2026-11-19T16:51:39.000Z","url":"https://x.com/KateClarkTweets/status/2123459198390243417"},{"id":"ronlabq67u2qvt78d7o11k6c7","title":"Anthropic IPO 融资 810 亿美元后，八个思考看后续挑战","summary":"Alex Kantrowitz 在 Anthropic IPO 当天提出八点观察。Anthropic 此次发行 9.8 亿股、每股 83 美元，融资 810 亿美元，股价即将站上 100 美元，估值接近 2 万亿美元，成为史上最大 IPO。","sourceName":"Big Technology（热点 RSS）","firstParty":false,"publishedAt":"2026-11-19T16:48:08.000Z","url":"https://www.bigtechnology.com/p/eight-thoughts-on-anthropics-ipo"},{"id":"w5f6ldj9b4r2rde1v5ajx44p2","title":"Anthropic 完成史上最大规模 IPO，Dario Amodei 敲钟演讲重申放慢 AI 开发节奏","summary":"Anthropic 周四在纳斯达克完成号称史上最大规模 IPO 上市，CEO Dario Amodei 在敲钟演讲中重申将放慢 AI 训练与部署节奏，不受商业或政治压力影响，保持 AI 在人类控制之下。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-19T16:19:41.000Z","url":"https://techcrunch.com/2026/11/19/at-nasdaq-opening-bell-anthropic-ceo-recommits-to-pacing-ai-development/"},{"id":"wy4i94u2e6f4gl8p0fapqxcbg","title":"Anthropic CEO Dario Amodei 与联合创始人 Daniela Amodei 参与 Nasdaq 开市敲钟","summary":"Anthropic CEO Dario Amodei、联合创始人 Daniela Amodei 等参与了 Nasdaq 开市敲钟仪式，标志着史上最大规模 IPO 的开始。图片来源标注为 Michael Nagle/Bloomberg News。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-19T15:42:12.000Z","url":"https://x.com/rohanpaul_ai/status/2123441720214106148"},{"id":"mmwz8pv1im8uklob62bq34kii","title":"Anthropic 股票或以每股 104 美元开盘，高于 83 美元 IPO 定价约 25%","summary":"Anthropic 股票预计以每股 104 美元开盘，较 83 美元的 IPO 发行价高出约 25%。","sourceName":"X：Kate Clark (@KateClarkTweets)","firstParty":false,"publishedAt":"2026-11-19T15:29:48.000Z","url":"https://x.com/KateClarkTweets/status/2123438598879871008"},{"id":"a8d06cpj4vy2dkdzazgsqsrwx","title":"Anthropic IPO 检验 AI 循环融资模式，Amazon 和 Google 持股市值约 3079 亿美元","summary":"TechCrunch 分析 Anthropic IPO 如何检验 AI 行业的循环融资模式。Amazon 14.7% 股份价值超 1590 亿美元，Google 13.7% 股份约 1490 亿美元；Nvidia、AMD、Microsoft、Broadcom、Micron、TSMC 还以 83 美元/股参与 260 亿美元私募。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-19T14:54:39.000Z","url":"https://techcrunch.com/2026/11/19/anthropics-ipo-puts-ais-circular-financing-boom-to-the-test/"},{"id":"zs46vfwtzhs7fzho1p17mfisf","title":"Anthropic 完成史上最大规模 IPO，其安全治理结构受到审视","summary":"The Verge 报道 Anthropic 完成 IPO，募资 813 亿美元，超过 SpaceX 成为史上估值最高的上市，完全稀释市值约 1.5 万亿美元。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-19T14:25:37.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1037459/anthropic-ipo-safe-ai-reputation-power-structure"},{"id":"f26jfj074e12cy839qpuo6t1z","title":"Anthropic IPO 定价每股 83 美元募资 813 亿美元，超越 SpaceX 纪录","summary":"Anthropic IPO 定价每股 83 美元，高于 70 至 78 美元目标区间，募资 813 亿美元，超过 SpaceX 6 月创下的 750 亿美元纪录，股票周四以代码 ANT 在纳斯达克交易。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-19T14:02:22.000Z","url":"https://the-decoder.com/anthropics-81-3-billion-ipo-shatters-spacexs-record-as-rising-rates-and-political-headwinds-shake-the-sector/"},{"id":"yu2rsdalw8maktdgtkdxou91v","title":"推文建议Claude订阅用户买入Anthropic股票","summary":"该推文建议Claude订阅用户成为Anthropic股东，称$ANT IPO价格为每股83美金。作者算账：Ultra订户一年2400美金、十年24000美金，约买250股，十年回报可覆盖全部订阅费且大概率盈利，并称十万亿市值应是十年后科技巨头入门标准。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-19T02:13:37.000Z","url":"https://x.com/indigox/status/2123238235526877663"},{"id":"c2a172rbdidbvyqk87irlvoba","title":"indigo 建议 Claude 订阅用户在 $ANT IPO 每股 83 美金时买入约 250 股覆盖订阅成本","summary":"indigo 建议 Claude 订阅用户买入 Anthropic 股票，成为公司股东。他提到 $ANT 次日 IPO 定价每股 83 美金，Ultra 订户一年成本 2400 美金、十年 24000 美金，购入约 250 股十年后的回报可覆盖全部订阅费并大概率盈利，并认为十年后十万亿市值将是科技巨头的入门标准。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-19T02:08:37.000Z","url":"https://x.com/indigox/status/2123236975780241812"},{"id":"am0vdstva0f00mrpzw0stslkw","title":"Anthropic IPO 定价每股 83 美元，发行 9.8 亿股 A 类股募资约 813 亿美元","summary":"Anthropic 以每股 83 美元定价 IPO，高于区间顶部 6%，发行 9.8 亿股 Class A 普通股，总募资约 813 亿美元，预计次日登陆纳斯达克。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-19T00:15:51.000Z","url":"https://x.com/rohanpaul_ai/status/2123208597303885970"},{"id":"x57gypzdz09onwjnccctd484i","title":"Anthropic IPO 定价 83 美元一股，即将登陆 Nasdaq","summary":"Anthropic 宣布 IPO 定价 83 美元/股，预计明日开始在 Nasdaq 交易。招股书由 SEC 于 2026 年 11 月 18 日宣布生效，承销方包括 Goldman Sachs 和 Morgan Stanley，公告原文见 anthropic.com。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-11-18T23:38:05.000Z","url":"https://x.com/indigox/status/2123199094680351131"},{"id":"hokjlogeo9373uw76eeb3f3mh","title":"Anthropic 将 IPO 定价定为每股 83 美元，明日登陆纳斯达克","summary":"Anthropic 宣布 IPO 定价为每股 83 美元，交易预计次日在纳斯达克开始。其 Class A 普通股注册声明已于 2026 年 11 月 18 日获 SEC 生效，本次发行仅通过招股说明书进行，承销方包括 Goldman Sachs 与 Morgan Stanley。","sourceName":"X：Anthropic (@AnthropicAI)","firstParty":false,"publishedAt":"2026-11-18T23:29:00.000Z","url":"https://x.com/AnthropicAI/status/2123196808675405860"},{"id":"gltv70anlfz4zx6b9guzvq43l","title":"Anthropic IPO 定价每股 $83，募资总额超 $94B 创纪录","summary":"Anthropic 将 IPO 定价定为每股 $83，高于 $70–$78 区间上沿 6.4%，报道称认购订单达发行股份的最多 6 倍，约 20% 份额留给散户（通常为 5%–10%）。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-18T22:37:43.000Z","url":"https://x.com/rohanpaul_ai/status/2123183901799846133"},{"id":"fbmacbdd7mkfush2x2wjfrpvy","title":"Anthropic 以每股 83 美元定价 IPO，估值达 1.5 万亿美元","summary":"Anthropic 据报道将 IPO 定价定为每股 83 美元，高于 70 至 78 美元的初始区间，完全稀释估值达 1.5 万亿美元，将于周四在纳斯达克以代码 ANT 上市。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-18T22:11:15.000Z","url":"https://techcrunch.com/2026/11/18/anthropic-reportedly-prices-ipo-at-83-a-share-above-projected-range/"},{"id":"kb0qscktovse2ejle2ubpcr2z","title":"Anthropic IPO 定价 83 美元，高于发行区间","summary":"Anthropic IPO 定价为每股 83 美元，高于此前发行区间。消息援引自 WSJ 报道。","sourceName":"X：Kate Clark (@KateClarkTweets)","firstParty":false,"publishedAt":"2026-11-18T21:41:58.000Z","url":"https://x.com/KateClarkTweets/status/2123169870552436802"},{"id":"jpjly30jyb7nf4muyzc0tc8fo","title":"Understanding AI 用19张图表解析AI行业现状","summary":"Understanding AI 发布19张图表，量化AI对美国经济和就业的影响。文中提到 Anthropic 即将上市，估值或超万亿美元，OpenAI 预计明年跟进；五大科技公司2026年第三季度资本支出达2300亿美元，AI收入年化运行率达3450亿美元，但新增企业采用放缓，年轻软件工程师就业明显下滑。","sourceName":"Timothy B. Lee：Understanding AI（RSS）","firstParty":false,"publishedAt":"2026-11-18T21:34:00.000Z","url":"https://www.understandingai.org/p/19-charts-that-explain-the-state"},{"id":"mlkeroda115hl0tiwrzs8njih","title":"Every 团队实测：我们让 AI 智能体买什么，什么时候仍坚持自己按下“购买”","summary":"ChatGPT 上周获得钱包功能后，Every 团队实测了让 AI 智能体代买杂货、机票等物品的体验，并讨论了哪些场景仍坚持自己按下“购买”。同期，Anthropic 在纳斯达克上市，开盘价 $111.50，市值 $2 万亿，募资 $81 亿，成为首家上市的前沿 AI 实验室。","sourceName":"Every：最新文章（网页）","firstParty":false,"publishedAt":"2026-11-18T16:00:00.000Z","url":"https://every.to/context-window/what-we-let-our-agents-buy"},{"id":"yxu549lhmsyp0qe8rstrheqlw","title":"Anthropic IPO 估值最高或达 1.4 万亿美元，华尔街提前造势散户争抢","summary":"据路透社报道，Anthropic 预计于当地时间 11 月 19 日登陆公开市场，IPO 估值最高可能达到 1.4 万亿美元。金融机构已推出 2 倍做多与做空 ETF 等挂钩产品，Vanda Research 预计上市将吸引约 2.5 亿美元散户净买入，为 SpaceX IPO 期间 1.18 亿美元纪录的两倍。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-18T10:45:07.760Z","url":"https://www.ithome.com/1/029/015.htm"},{"id":"hpczcbqe8agr7jffko2cnsp31","title":"Anthropic 拟将 IPO 定价上调至 $80 以上，估值或达 $1.6T","summary":"据 WSJ，Anthropic 预计将 IPO 定价上调至 $70 至 $78 区间之上，可能超过 $80 一股，其顾问已讨论 $1.5T 或 $1.6T 的估值，高于此前约 $1.33T。按申报区间计算，IPO 规模约 $61B，另有 $26B 私募配售，其中 Google 和 Nvidia 各以 IPO 价格认购约 $10B。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-18T00:15:01.000Z","url":"https://x.com/rohanpaul_ai/status/2122845999387602999"},{"id":"cxpq4gwitsj6r05zjpphx9agc","title":"Anthropic 获准在纳斯达克上市，代码 ANT，发行价每股 70~78 美元","summary":"根据 SEC 11 月 17 日公示的文件，Anthropic 的 A 类普通股获准在纳斯达克全球精选市场上市，代码 ANT，发行价区间维持每股 70 至 78 美元。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-18T00:12:10.273Z","url":"https://www.ithome.com/1/028/599.htm"},{"id":"h9i8o2kzwr1fj3op3i48gcyhb","title":"Anthropic IPO 后 Amazon 与 Google 将合计持股近 30%","summary":"Anthropic 披露 IPO 相关投资细节：Amazon 持股将达 14.7%，全部转换可转债可至 23.8%；Google 持股 13.7%，均为无投票权股份。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-17T22:29:05.000Z","url":"https://techcrunch.com/2026/11/17/amazon-and-google-will-together-own-nearly-30-of-anthropic-after-its-ipo/"},{"id":"mqb1ivb69ry2hmuc65xst4mle","title":"Anthropic 因投资者需求旺盛计划上调 IPO 发行价","summary":"记者 Kate Clark 引述 WSJ 报道，Nvidia 相关风波并未拖慢 Anthropic 的 IPO 进程，由于投资者需求旺盛，公司计划上调发行价。报道由 Kate Clark 与 WSJ 记者 @cdriebusch、@BenDummett 合作完成。","sourceName":"X：Kate Clark (@KateClarkTweets)","firstParty":false,"publishedAt":"2026-11-17T17:04:26.000Z","url":"https://x.com/KateClarkTweets/status/2122737640306884838"},{"id":"o0z8uukw36ic6txpxi29o96ep","title":"Anthropic IPO 定价每股 $83.00，11 月 19 日以代码 ANT 登陆纳斯达克","summary":"Anthropic, PBC 宣布其 IPO 定价为每股 $83.00，共发行 980,000,000 股 Class A 普通股，其中 956,351,354 股由公司出售，23,648,646 股由部分出售股东出售，公司不会获得后者收益。","sourceName":"Anthropic：Newsroom（网页）","firstParty":true,"publishedAt":"2026-11-17T16:00:00.000Z","url":"https://www.anthropic.com/news/anthropic-prices-initial-public-offering"},{"id":"g00g4zgmnmxgh069cxc07h5ko","title":"FT：SBF 投入 Anthropic 的 5 亿美元按 IPO 预期价格约值 370 亿美元","summary":"据 FT，Sam Bankman-Fried 当年投入 Anthropic 的 5 亿美元，按下周预期 IPO 价格约值 370 亿美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-14T00:31:20.000Z","url":"https://x.com/rohanpaul_ai/status/2121400552927985769"},{"id":"zqbqdxdjvxdhrl7z9zzwvi9qa","title":"多家银行以美国出口管制为由，拒绝中国大陆和香港投资者参与 Anthropic IPO","summary":"据 Bloomberg 报道，多家银行拒绝中国大陆和香港投资者的认购订单，或认为其获配可能性很低，部分人士以美国出口管制规则 ITAR 为由。Anthropic 不予置评，此次 IPO 由 Goldman Sachs 和 Morgan Stanley 牵头，另有 20 家银行参与，股票预计 11 月 18 日定价后在 Nasdaq 以代码 ANT 交易。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-13T18:01:53.000Z","url":"https://the-decoder.com/banks-bar-chinese-and-hong-kong-investors-from-anthropic-ipo-over-us-export-controls/"},{"id":"ir04ccbh63mo2xavryooeewvr","title":"Anthropic IPO 获六倍超额认购，有望成史上最大规模 IPO","summary":"据 Bloomberg 报道，Anthropic 的 IPO 订单超出可售股份六倍，公司及其联合创始人拟通过公开发行募资至多 644 亿美元，另通过私募募资 260 亿美元，目标估值约 1.4 万亿美元，若达成将超过 SpaceX 的 IPO。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-13T15:15:08.000Z","url":"https://the-decoder.com/anthropics-ipo-is-six-times-oversubscribed-and-on-track-to-become-the-largest-public-offering-in-history/"},{"id":"k99zjo9hbtous9r6vmmz7pxyh","title":"Anthropic 官宣首次公开募股（IPO）","summary":"Anthropic 官方宣布启动首次公开募股（IPO），并公布入口 ipo.anthropic.com。Anthropic 已向 SEC 提交注册声明及招股说明书，证券在注册声明生效前不得出售，初步招股说明书可经高盛与摩根士丹利获取。","sourceName":"X：Anthropic (@AnthropicAI)","firstParty":false,"publishedAt":"2026-11-12T11:30:46.000Z","url":"https://x.com/AnthropicAI/status/2120841731302154708"},{"id":"xi0y19pbadxpvgcmzsm7c5byg","title":"Anthropic IPO 路演视频披露多芯片策略与算力乘数细节","summary":"Simon Willison 整理了 Anthropic IPO 路演视频的转录稿，称其中包含此前未公开的业务信息。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-11T15:11:59.000Z","url":"https://simonwillison.net/2026/Nov/11/anthropic-ipo-roadshow/"},{"id":"r5kn7uexy6jx97qwxwvnpqrom","title":"Anthropic IPO 拟募资最高 90.4B 美元，或成史上最大上市","summary":"Bloomberg 报道 Anthropic IPO 已获数倍于发行份额的订单，主要来自大型机构投资者的锚定级意向。公司通过 IPO 加私募配售寻求最高 $90.4B，将超过 SpaceX 的 $85.7B 纪录成为史上最大上市，完全稀释估值目标约 $1.4T；Goldman Sachs 和 Morgan Stanley 牵头共 22 家银行，股票将以 ANT 在纳斯达克全球精选市场交易。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T14:38:51.000Z","url":"https://x.com/rohanpaul_ai/status/2120526677247939001"},{"id":"ajjv9abs8vd20j05emcig98ai","title":"WSJ：Anthropic 7 位创始人 IPO 各套现约 2.5 亿美元并保留控制权","summary":"WSJ 报道，Anthropic 7 位创始人将在 IPO 中各出售约 2.5 亿美元股票，每人保留约 180 亿美元持仓。据公司文件，每人出售近 3.4M 股，发行价区间预计 70 至 78 美元，上市预计下周进行，估值接近 1.3 万亿美元，募资 800 亿美元以上，部分通过包括 Google 在内的私募配售。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T05:47:04.000Z","url":"https://x.com/rohanpaul_ai/status/2120392847505715324"},{"id":"m7ul4psbkb5zyp0t254fr986o","title":"Anthropic 投资需求火热，承销商拟将 IPO 目标估值上调回 $1.5T 或更高","summary":"FT 报道，因投资者需求旺盛，Anthropic 承销商计划上调 IPO 定价，把目标估值拉回 $1.5T 或更高。周二文件设定 $70-$78 的发行区间，计入员工期权和受限股后对应 $1.26T-$1.41T 估值；若定价超出区间，募资将超过 $100B，其中 Google、Nvidia 和 Microsoft 将按 IPO 价格投资 $26B。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T00:58:06.000Z","url":"https://x.com/rohanpaul_ai/status/2120320127484969162"},{"id":"eo7ozgw5sry6i4d0al4cu43py","title":"Anthropic S-1 披露七位创始人 IPO 各套现约 2.5 亿美元","summary":"Anthropic 的 S-1 文件显示，七位联合创始人每人将出售 3,378,378 股，按 70 至 78 美元的发行价区间，每人套现约 2.36 亿至 2.64 亿美元。IPO 估值可能达到 1.4 万亿美元，七人通过 Class F 超级投票权股份合计控制 51.1% 的投票权。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T19:57:52.000Z","url":"https://techcrunch.com/2026/11/10/all-7-anthropic-founders-will-each-cash-out-about-250m-in-ipo/"},{"id":"j8x08g5wo30akk4mast68n79d","title":"Anthropic 再次修订 S-1：宣布已达责任扩展政策能力阈值，IPO 定价 $70-$78","summary":"Anthropic 再次修订 IPO 申请文件 S-1（Amendment No. 2），宣布已越过其 Responsible Scaling Policy 设定的阈值，即 AI 正大幅加快 AI 研究速度、需更强安全检查。这一判断基于其对未来模型的预期而非现有模型的表现，一周前的文件还只说\"可能即将\"越过。文件同时将 IPO 发行价定为每股 $70 至 $78。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T19:04:06.000Z","url":"https://x.com/rohanpaul_ai/status/2120231037569790385"}]},"2d0a9c1a-2a0a-41b6-a7ef-776ef03a783b":{"publicId":"2d0a9c1a-2a0a-41b6-a7ef-776ef03a783b","title":"200万诱饵请求测出AI服务链数据外泄","status":"active","sourceCount":5,"reportCount":5,"firstReportAt":"2026-11-20T20:59:08.000Z","latestAt":"2026-11-22T12:07:56.000Z","latest":"Dragos研究揭示低价AI推理服务商窃取密钥并窥探用户请求","digest":"安全公司 Dragos 首席研究官 HD Moore 在 2026 年 7 月至 11 月间，经 OpenRouter 等 AI 路由向多家 AI 服务商发送约 200 万条带假凭证和可追踪诱饵的请求，发现提示词被窃、转售商外传数据、隐私设置未被执行等问题。至少三家服务商出现遭入侵迹象，被盗的数百个 AWS 密钥在数小时内被试用并用于搜索 S3 存储；部分标记为“零数据保留”（ZDR）的请求，其私密网址数日后仍被抓取。The Decoder 报道称，受影响服务商包括 Novita、Phala 和 Together。\n\nOpenRouter 回应称，未发现 OpenRouter 本身被入侵，问题出在部分推理提供商的数据泄露或数据政策未被执行。OpenRouter 称已下架 3 家提供商、将 125 个端点移出 ZDR 资格并通知受影响客户；被移出的端点须提供适当保证并通过验证，才能恢复 ZDR 资格。\n\nMoore 建议敏感业务可本地部署或直接选择可信服务商；Dragos 还建议企业控制 AI 请求的路由方式、检查隐私设置并植入自有的金丝雀令牌。","digestUpdatedAt":"2026-11-22T13:08:41.175Z","reports":[{"id":"kbrosmbvldj069ds87zid0wlp","title":"Dragos研究揭示低价AI推理服务商窃取密钥并窥探用户请求","summary":"Dragos安全研究人员在2026年7月至11月期间向AI服务商发送约200万条含假凭证的请求，发现至少三家服务商遭入侵，攻击者窃取数百个AWS密钥并在数小时内试用、搜索S3存储，部分攻击者还使用了AI攻击工具ARTEX。研究还发现，部分市场转售商无需利用漏洞即可读取客户请求，仅需以最低价上架模型并开启日志记录。隐私设置如“零数据保留”（ZDR）常被忽视。OpenRouter随后从平台移除三家服务商并撤销125个端点的ZDR批准，同时邮件通知受影响用户。受影响服务商包括Novita、Phala和Together，已发布初步安全报告。Dragos建议企业控制AI请求路由方式、检查隐私设置并植入自有的金丝雀令牌。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-22T12:07:56.000Z","url":"https://the-decoder.com/security-researchers-show-how-cheap-ai-inference-providers-steal-keys-and-snoop-on-users/"},{"id":"yj1o6pemhdr7th9xt779xzt0m","title":"OpenRouter 回应推理提供商数据处理问题：下架 3 家并收紧 ZDR 资格","summary":"安全研究人员发现 OpenRouter 平台上部分推理提供商存在数据处理问题，但未波及 OpenRouter 本身。OpenRouter 已下架 3 家提供商、将许多端点移出 ZDR 资格范围并通知受影响客户，还计划把研究人员的测试纳入持续检查，完整更新发布在其博客。","sourceName":"X：OpenRouter (@OpenRouter)","firstParty":false,"publishedAt":"2026-11-22T01:32:38.000Z","url":"https://x.com/OpenRouter/status/2124315081899200715"},{"id":"dvvqir3buzkemt3nqplef9omx","title":"OpenRouter 因推理提供商数据处理事件下架三家提供商并移除 125 个 ZDR 端点","summary":"OpenRouter 针对安全研究人员报告的部分推理提供商数据泄露或数据政策未被执行问题发布公告，称未发现 OpenRouter 本身被入侵。","sourceName":"OpenRouter：Announcements（RSS）","firstParty":true,"publishedAt":"2026-11-22T00:00:00.000Z","url":"https://openrouter.ai/blog/announcements/data-processing-incidents-on-inference-providers/"},{"id":"n1sb4nib4897yds1wpi0dgwky","title":"近 200 万条诱饵请求揭示 AI 服务链隐私泄露：零数据保留也失效","summary":"安全公司 Dragos 首席研究官 HD Moore 向多家 AI 服务商发送近 200 万条带可追踪诱饵的请求，发现提示词被窃、转售商外传数据及隐私设置未被执行等问题。至少三家服务商出现遭入侵迹象，被盗诱饵密钥被用于数万次云服务接口调用；部分标记零数据保留的请求其私密网址数日后仍被抓取，Moore 建议敏感业务可本地部署或直接选择可信服务商。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-21T02:03:24.083Z","url":"https://www.ithome.com/1/030/322.htm"},{"id":"agm7klro03kcu9weuix1bt4su","title":"研究者向 AI 供应链埋入 200 万个金丝雀，揭露敏感数据泄露","summary":"研究者在经过 OpenRouter 等 AI 路由的请求中埋入 200 万个金丝雀链接，测试敏感信息是否会沿 AI 服务链泄露，结果显示这些数据像筛子一样大量外泄。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-11-20T20:59:08.000Z","url":"https://arstechnica.com/security/2026/11/a-leaky-ai-supply-chain-is-exposing-secret-user-data-at-an-alarming-rate/"}]},"1dac546d-9364-43da-99ca-d494fb94d71c":{"publicId":"1dac546d-9364-43da-99ca-d494fb94d71c","title":"X Square Robot发布WALL-OSS-1.0并开放API","status":"active","sourceCount":1,"reportCount":2,"firstReportAt":"2026-11-23T07:30:35.000Z","latestAt":"2026-11-23T08:29:40.000Z","latest":"自变量开放WALL-OSS-1.0 API申请","digest":"X Square Robot 发布具身基础模型 WALL-OSS-1.0，采用原生 VLA 预训练，将视觉、语言与动作融合，使机器人能处理未预先定义的任务。公司称，该模型在 312 个真实机器人任务上实现 55.1% 零样本成功率，无需任务专属演示或微调。\n\n配套的 XR Harness 可将“收拾桌子”这类高层指令转化为多步骤协调动作。技术博客、GitHub 仓库和 API 均已公开。\n\n随后公司上线 WALL-API-1.0，通过 API 开放 WALL-OSS-1.0 访问权限，面向研究人员、开发者和企业；API Key 需通过指定邮箱申请。","digestUpdatedAt":"2026-11-23T10:55:44.800Z","reports":[{"id":"kh945941izcwpvjhgqqdhemab","title":"自变量开放WALL-OSS-1.0 API申请","summary":"🚀 WALL-API-1.0 现已上线！\n\n我们通过 API 开放 WALL-OSS-1.0 的访问权限，让全球的研究人员、开发者和企业能够探索并构建真实世界的具身智能应用。\n\n🔗 申请 API 访问：https://x2robot.com/docs/quantax1pro/v1/model-development/wallx-api/api-usage-instruction\n\n📩 API Key 申请：wallxapi@x2robot.com","sourceName":"X：自变量 X Square (@XSquareRobot)","firstParty":false,"publishedAt":"2026-11-23T08:29:40.000Z","url":"https://x.com/XSquareRobot/status/2124782423309209875"},{"id":"qn7g89zaoh4cudd1lrd2o1wl8","title":"X Square Robot 发布 WALL-OSS-1.0 具身基础模型","summary":"X Square Robot 发布具身基础模型 WALL-OSS-1.0，采用原生 VLA 预训练，融合视觉、语言与动作，使机器人适应未预先定义的任务。模型在 312 个真实机器人任务上实现 55.1% 零样本成功率，无需任务专属演示或微调。配套的 XR Harness 可将「收拾桌子」这类高层指令转化为多步骤协调动作，技术博客、GitHub 仓库和 API 均已公开。","sourceName":"X：自变量 X Square (@XSquareRobot)","firstParty":false,"publishedAt":"2026-11-23T07:30:35.000Z","url":"https://x.com/XSquareRobot/status/2124767551959757162"}]}}};
